            $h .= '<div class="strip' . ( function_exists( 'sahel_pcs_html' ) ? sahel_pcs_html( 'sale' ) : '"' ) . '>' . do_shortcode( '[products limit="' . ( function_exists( 'sahel_pcs_limit' ) ? sahel_pcs_limit( 'sale' ) : 8 ) . '" columns="4" on_sale="true"]' ) . '</div></div></section>';
