    $rad = (int) get_theme_mod( 'sahel_radius', 22 );
    echo '<style id="sahel-extra">:root{--rad:' . $rad . 'px}
.btn{border-radius:var(--rad)}
.prod-card,.cat-card,.post-card,.feat{border-radius:var(--rad)}
.page-card{border-radius:calc(var(--rad) + 6px)}
