            . '@media(min-width:2400px){:root{--wrap-w:max(' . $ww . 'px,min(84vw,2240px));--ui:1.4}}'
            . '@media(min-width:3200px){:root{--wrap-w:max(' . $ww . 'px,min(84vw,3000px));--ui:1.75}}';
    }
    echo '<style id="sahel-v55">' . $dyn . <<<'SHCSS55'
