.sl-showcase:is(.sc-pos-top,.sc-pos-bottom).sc-st-buy .sc-item img,.sl-showcase:is(.sc-pos-top,.sc-pos-bottom).sc-st-featured .sc-item img{width:64px;height:64px;flex-shrink:0}
