    foreach ( $sets as $k => $s ) { echo '<a class="' . ( $k === $g ? 'on' : '' ) . '" href="' . $u( array( 'g' => $k, 'vw' => $vw, 'dm' => $dm ) ) . '">' . esc_html( $s[0] ) . ' (' . esc_html( sahel_fa( count( $s[1] ) ) ) . ')</a>'; }
