    $sec( 'sahel_promo', 'sahel_p_mobile', 14, 'تبلیغ شناور گوشه سایت' );
    $sec( 'sahel_scrolltop', 'sahel_p_mobile', 16, 'دکمه بالا/پایین صفحه' );
