      if(st.c&&(' '+d.c+' ').indexOf(' '+st.c+' ')<0)return false;
      if(st.min!=null&&p<st.min)return false;if(st.max!=null&&p>st.max)return false;
      if(st.sale&&d.s!=='1')return false;if(st.stock&&d.k!=='1')return false;return true;});
