    $add( 'cover_title', 'کاتالوگ محصولات', 'sanitize_text_field', array( 'label' => '📕 جلد — عنوان', 'type' => 'text' ) );
    $add( 'cover_sub', '', 'sanitize_text_field', array( 'label' => '📕 جلد — زیرعنوان (خالی = نام فروشگاه)', 'type' => 'text' ) );
