    $add( 'back_text', 'از همراهی شما سپاسگزاریم. برای خرید و دیدن جزئیات هر محصول، روی آن بزنید.', 'wp_kses_post', array( 'label' => '📗 پشت جلد — متن', 'type' => 'textarea' ) );
