        $w->add_control( new WP_Customize_Color_Control( $w, $id, array( 'label' => $label, 'section' => $sec, 'priority' => $prio ) ) );
    };
    $img = function ( $id, $label, $sec, $prio = 10 ) use ( $w ) {
